                const contentContainer = document.getElementById('modal-character-content');
                const interactionsContainer = document.getElementById('modal-character-interactions');

                contentContainer.innerHTML = '';
                interactionsContainer.innerHTML = '';
                nameEl.textContent = character.isProtagonist ? (character.info[character.infoHeaders.indexOf("人物名称")] || '主角') : (character.info[character.infoHeaders.indexOf('姓名')] || '未知角色');

                const descFragment = document.createDocumentFragment();

                if (character.isProtagonist) {
                    const statusHeaders = character.statusHeaders;
                    const pDetails = {
                        ...Object.fromEntries(character.infoHeaders.map((h, i) => [h, character.info[i]])),
                        ...Object.fromEntries(statusHeaders.map((h, i) => [h, character.status[i]]))
                    };

                    const statsString = pDetails["当前属性"] || "";
                    const stats = Object.fromEntries(statsString.split(/[,，\/]/).map(s => s.split(/[:：]/)).map(([k,v]) => [k.trim(), parseInt(v) || 0]));

                    const details = [{ label: '性别/年龄', value: pDetails["性别/年龄"] }, { label: '武魂', value: pDetails["武魂"] }, { label: '外貌', value: pDetails["外貌特征"] }, { label: '职业/身份', value: pDetails["职业/身份"] }, { label: '背景', value: pDetails["背景故事"] }, { label: '性格', value: pDetails["性格特点"] }, { label: '状态', value: pDetails["当前状态"] }];
                    details.forEach(detail => {
                        if (detail.value) {
                            const p = document.createElement('p');
                            p.innerHTML = `<strong>${detail.label}:</strong> ${detail.value}`;
                            descFragment.appendChild(p);
                        }
                    });

                } else {
                    const details = [
                        { label: '性别/年龄', value: character.info[character.infoHeaders.indexOf('性别/年龄')] }, 
                        { label: '武魂', value: character.info[character.infoHeaders.indexOf('武魂')] }, 
                        { label: '外貌', value: character.info[character.infoHeaders.indexOf('外貌特征')] }, 
                        { label: '职业/身份', value: character.info[character.infoHeaders.indexOf('职业/身份')] }, 
                        { label: '魂力等级', value: character.info[character.infoHeaders.indexOf('魂力等级')] }, 
                        { label: '魂技', value: character.info[character.infoHeaders.indexOf('魂技')] },
                        { label: '性格', value: character.info[character.infoHeaders.indexOf('性格特点')] }, 
                        { label: '背景', value: character.info[character.infoHeaders.indexOf('背景故事')] }, 
                        { label: '与主角关系', value: character.info[character.infoHeaders.indexOf('与主角关系')] },
                        { label: '当前状态', value: character.info[character.infoHeaders.indexOf('当前状态与倒计时')] }
                    ];
                    details.forEach(detail => {
                        if (detail.value) {
                            const p = document.createElement('p');
