                contentContainer.appendChild(descFragment);

                const interactionHeaders = ["互动1", "互动2", "互动3", "互动4"];
                const interactionData = character.isProtagonist ? character.status : character.info;
                const sourceHeaders = character.isProtagonist ? character.statusHeaders : character.infoHeaders;
                const interactFragment = document.createDocumentFragment();

                interactionHeaders.forEach(header => {
